templates.templates["Giocatore1"] = {
    name: "Giocatore1",
    depth: 3,
    blendMode: PIXI.BLEND_MODES.NORMAL,
    visible: true,
    baseClass: "AnimatedSprite",
    
            texture: "G1",
        animationFPS: 30,
        playAnimationOnStart: true,
        loopAnimation: true,
    behaviors: JSON.parse('[]'),
    onStep: function () {
        /* 🐱👉 template Giocatore1 — On frame start event (core_OnStep) */
{
if (!pause.isPaused) {
    var maxSpeed = 240 - 10 * this.spazzaturaGrande.length;
    var friction = 0.05

    //direzione del personaggio
    if (actions.P1MoveY.down) this.scale.y = this.defaultScale.y * (actions.P1MoveY.value >= 0 ? 1 : -1);
    if (actions.P1MoveX.down) this.scale.x = this.defaultScale.x * (actions.P1MoveX.value > 0 ?  -1 : 1);
    if (actions.P1MoveY.value == -1) {
        this.rotation = (actions.P1MoveX.down) ? (this.scale.x > 0 ? -45 : 45) : 0;
    } else this.rotation = 0;

    // Gestione movimento e collisione
    if (this.hasCollidedWithEnemy) {
        this.hspeed = !place.occupied(this, this.x + 3 * actions.P1MoveX.value, this.y, "Terreno") ? this.hspeed : (-this.hspeed*0.4);
        this.vspeed = !place.occupied(this, this.x, this.y + 3 * actions.P1MoveY.value, "Terreno") ? this.vspeed : (-this.vspeed*0.4);

    } else {
        var targetSpeedX = actions.P1MoveX.down ? maxSpeed * actions.P1MoveX.value : 0;
        var targetSpeedY = actions.P1MoveY.down ? maxSpeed * actions.P1MoveY.value : 0;

        this.hspeed += (targetSpeedX - this.hspeed) * friction;
        this.vspeed += (targetSpeedY - this.vspeed) * friction;
        this.hspeed = place.occupied(this, this.x + 10 * actions.P1MoveX.value, this.y, "Terreno") ? 0 : this.hspeed;
        this.vspeed = place.occupied(this, this.x, this.y + 10 * actions.P1MoveY.value, "Terreno") ? 0 : this.vspeed;
    }

    // "Rendering" spazzatura grande ancorata al giocatore
    var offsetSpazzatura = 40;

    if (actions.P1Reset.down) {
        this.x = this.spawnX;
        this.y = this.spawnY;
        this.hspeed = 0;
        this.vspeed = 0;
        
        if (this.spazzaturaGrande.length > 0) {
            for (let i of this.spazzaturaGrande) i.kill = true;
            this.spazzaturaGrande = [];
        }
        this.air = 3
    }

    for (let i = 0; i < this.spazzaturaGrande.length; i++) { // Yay inefficienza!!
        this.spazzaturaGrande[i].x = this.x;
        this.spazzaturaGrande[i].y = this.y + offsetSpazzatura * i;
    }

    this.move();
}
}
/* 🐱👉 template Giocatore1 — Collision with a group event (place_collisionCGroup) */
{
    const other = place.occupied(this, 'Nemici');
    if (templates.valid(other)) {
        this.enemyCollision()
    }
}

/* 🐱👉 template Giocatore1 — Collision with a template event (place_collisionTemplate) */
{
    const other = place.meet(this, 'ZonaPunti');
    if (templates.valid(other)) {
        if (this.spazzaturaGrande.length > 0) {

    sounds.play('Spazzatura depositata');
    scoreP1 += 100 * this.spazzaturaGrande.length;
    for (let i of this.spazzaturaGrande) i.kill = true;

    this.spazzaturaGrande = [];
}
    this.air = 3
    }
}


    },
    onDraw: function () {
        /* 🐱👉 template Giocatore1 — On frame end event (core_OnDraw) */
{
if (place.occupied(this, this.x, this.y, "Terreno")) {
    let trovato = false;
    let raggio = 2; // Quanto lontano cerchiamo ogni volta
    let maxTentativi = 20; // Per evitare che il gioco si blocchi se sei sepolto nel terreno
    
    // Cerchiamo nelle 8 direzioni attorno al giocatore, espandendo il cerchio
    for (let i = 1; i <= maxTentativi; i++) {
        let dist = i * raggio;
        
        // Array di direzioni: Destra, Sinistra, Sopra, Sotto e Diagonali
        let direzioni = [
            {dx: dist, dy: 0}, {dx: -dist, dy: 0}, 
            {dx: 0, dy: dist}, {dx: 0, dy: -dist},
            {dx: dist, dy: dist}, {dx: -dist, dy: dist},
            {dx: dist, dy: -dist}, {dx: -dist, dy: -dist}
        ];

        for (let dir of direzioni) {
            // Controlliamo se la posizione (X + dx, Y + dy) è libera
            if (!place.occupied(this, this.x + dir.dx, this.y + dir.dy, "Terreno")) {
                this.x += dir.dx;
                this.y += dir.dy;
                trovato = true;
                break; // Esci dal ciclo delle direzioni
            }
        }
        
        if (trovato) break; // Esci dal ciclo dei tentativi
    }
}
}

    },
    onDestroy: function () {
        
    },
    onCreate: function () {
        /* 🐱👉 template Giocatore1 — On create event (core_OnCreate) */
{
    this.hasCollidedWithEnemy = false;
    this.spazzaturaGrande = [];

    this.animationSpeed = 0.12;
    this.defaultScale = {
        x: this.scale.x,
        y: this.scale.y
    }

    this.spawnX = this.x;
    this.spawnY = this.y;
    this.air = 3

    this.enemyCollision = function () {
        if (!this.hasCollidedWithEnemy && !pause.isPaused) {
            this.hspeed = -this.hspeed;
            this.vspeed = -this.vspeed;
            sounds.play('Danno');

            if (this.spazzaturaGrande.length > 0) {
                let spazzaturaCaduta = this.spazzaturaGrande[this.spazzaturaGrande.length - 1];

                let maxDist = 120;
                let targetX, targetY;
                let puntoTrovato = false;
                let tentativi = 0;

                while (!puntoTrovato && tentativi < 10) {
                    let targetDeltaX = (Math.random() * maxDist) - (maxDist / 2);
                    let targetDeltaY = (Math.random() * maxDist) - (maxDist / 2);

                    targetX = this.x + targetDeltaX;
                    targetY = this.y + targetDeltaY;

                    if (!place.occupied(spazzaturaCaduta, targetX, targetY, 'Terreno')) {
                        puntoTrovato = true;
                    }
                    tentativi++;
                }
                if (!puntoTrovato) {
                    targetX = this.x;
                    targetY = this.y;
                }

                spazzaturaCaduta.x = targetX;
                spazzaturaCaduta.y = targetY;

                spazzaturaCaduta.isCollected = false;

                this.spazzaturaGrande.pop();
                if (enemyDamage) this.aria -= 0.2
            }

            this.hasCollidedWithEnemy = true;

            var blinkInterval = setInterval(() => {
                if (!pause.isPaused) this.alpha = this.alpha == 1 ? 0.2 : 1;
            }, 100);

            setTimeout(() => {
                this.hasCollidedWithEnemy = false;
                clearInterval(blinkInterval);

                this.alpha = 1;
            }, 1500);

            if (enemyDamage) this.air -= 0.2
        }
    }
}

    },
    extends: {
    "cgroup": "Giocatore",
    "editor:myCollidingCGroups": [
        "Terreno"
    ]
}
};
templates.list['Giocatore1'] = [];
        
