templates.templates["Pesce Palla"] = {
    name: "Pesce Palla",
    depth: 10,
    blendMode: PIXI.BLEND_MODES.NORMAL,
    visible: true,
    baseClass: "AnimatedSprite",
    
            texture: "fish_brown",
        animationFPS: 4,
        playAnimationOnStart: true,
        loopAnimation: true,
    behaviors: JSON.parse('[]'),
    onStep: function () {
        /* 🐱👉 template Pesce Palla — On frame start event (core_OnStep) */
{
if (!pause.isPaused) {
    // 1. Calcoliamo di quanti pixel ESATTI si muoverà in questo frame
    // Moltiplicando per u.time, il passo sarà perfetto (es. 2.5 pixel)
    let passo = this.velocitaPesce * u.time;

    // --- DEBUG: SE SEI GIA' INCASTRATO ---
    // Questo ti scriverà in console se il pesce nasce già dentro il muro!
    if (place.occupied(this, this.x, this.y, 'Terreno')) {
        console.log("ALLARME: Sono nato dentro il muro alle coordinate " + this.x + ", " + this.y);
    }

    // 2. MOVIMENTO A DESTRA
    if (this.versoDestra) {
        // Controlla se il prossimo ESATTO passo tocca il muro
        if (place.occupied(this, this.x + passo, this.y, 'Terreno')) {
            this.versoDestra = false; // Gira
            this.scale.x = -this.baseScaleX;
        } else {
            this.x += passo; // Muoviti davvero
        }
    } 
    // 3. MOVIMENTO A SINISTRA
    else {
        // Controlla se il prossimo ESATTO passo tocca il muro a sinistra
        if (place.occupied(this, this.x - passo, this.y, 'Terreno')) {
            this.versoDestra = true; // Gira
            this.scale.x = this.baseScaleX;
        } else {
            this.x -= passo; // Muoviti davvero
        }
    }
}
// NOTA: NON usare this.move() qui sotto! Muoviamo this.x manualmente.
}

    },
    onDraw: function () {
        
    },
    onDestroy: function () {
        
    },
    onCreate: function () {
        /* 🐱👉 template Pesce Palla — On create event (core_OnCreate) */
{
this.speed = 150;
this.direction = 0;
this.scale.x = .8;
this.scale.y = .8;

// Usiamo variabili nostre invece di quelle di sistema
this.velocitaPesce = 150; // Velocità in pixel al secondo (cambiala come vuoi)
this.versoDestra = true;  // Scegli se parte andando a destra o sinistra
this.baseScaleX = this.scale.x;
}

    },
    extends: {
    "cgroup": "Nemici",
    "editor:myCollidingCGroups": []
}
};
templates.list['Pesce Palla'] = [];
        
