templates.templates["Spazzatura_grande"] = {
    name: "Spazzatura_grande",
    depth: 0,
    blendMode: PIXI.BLEND_MODES.NORMAL,
    visible: true,
    baseClass: "AnimatedSprite",
    
            texture: "Grande1",
        animationFPS: 30,
        playAnimationOnStart: false,
        loopAnimation: true,
    behaviors: JSON.parse('[]'),
    onStep: function () {
        /* 🐱👉 template Spazzatura_grande — Collision with a group event (place_collisionCGroup) */
{
    const other = place.occupied(this, 'Giocatore');
    if (templates.valid(other)) {
        if (!this.isCollected && !place.occupied(this, this.x, this.y, 'Giocatore').hasCollidedWithEnemy) {
    sounds.play('Raccolta');
    this.isCollected = true;
    place.occupied(this, this.x, this.y, 'Giocatore').spazzaturaGrande.push(this);
}
    }
}

/* 🐱👉 template Spazzatura_grande — On frame start event (core_OnStep) */
{
this.move();

}

    },
    onDraw: function () {
        
    },
    onDestroy: function () {
        /* 🐱👉 template Spazzatura_grande — On destroy event (core_OnDestroy) */
{
    do {
        var x = Math.floor(random.range(rooms.current.maxX, rooms.current.minX));
        var y = Math.floor(random(rooms.current.maxY));
    } while (place.occupied(this, x, y, 'outOfBounds'));

    setTimeout(() => {
        templates.copy('Spazzatura_grande', x, y);
        sounds.play('Generazione Spazzatura');
    }, 2000 + Math.floor(Math.random() * 3 * 1000));

    emitters.stop(this.puzza)

}

    },
    onCreate: function () {
        /* 🐱👉 template Spazzatura_grande — On create event (core_OnCreate) */
{
this.isCollected = false;
sounds.play('Generazione Spazzatura');
this.tex = "Grande" + Math.floor(Math.random() * 2 + 1);
this.scale.x = 1.3
this.scale.y = 1.3
this.puzza = emitters.follow(this,'Puzza')
}

    },
    extends: {
    "cgroup": "",
    "editor:myCollidingCGroups": []
}
};
